static uint32_t xs32(uint32_t *state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *state = x;
    return x;
}

static uint32_t rand_u8(uint32_t *state) {
    return xs32(state) % 256u;
}

static void run_case(int *case_no, unsigned char r, unsigned char g,
                      unsigned char b) {
    cb_rgb_255 in;
    cb_rgb_255 out;
    in.R = r;
    in.G = g;
    in.B = b;
    out = tritanopia(in);
    printf("case %d in=%u,%u,%u out=%u,%u,%u\n", *case_no, (unsigned)r,
           (unsigned)g, (unsigned)b, (unsigned)out.R, (unsigned)out.G,
           (unsigned)out.B);
    (*case_no)++;
}

int main(void) {
    int case_no = 0;
    static const unsigned char grid[] = {0,   1,   2,   16,  32,  63,
                                          64,  100, 127, 128, 150, 191,
                                          192, 200, 253, 254, 255};
    size_t n_grid = sizeof(grid) / sizeof(grid[0]);
    size_t i, j, k;

    run_case(&case_no, 0, 0, 0);
    run_case(&case_no, 255, 255, 255);
    run_case(&case_no, 255, 0, 0);
    run_case(&case_no, 0, 255, 0);
    run_case(&case_no, 0, 0, 255);
    run_case(&case_no, 255, 255, 0);
    run_case(&case_no, 255, 0, 255);
    run_case(&case_no, 0, 255, 255);
    run_case(&case_no, 128, 128, 128);
    run_case(&case_no, 1, 1, 1);
    run_case(&case_no, 254, 254, 254);

    for (i = 0; i < 256; i++) {
        run_case(&case_no, (unsigned char)i, (unsigned char)i,
                 (unsigned char)i);
    }

    for (i = 0; i < n_grid; i++) {
        for (j = 0; j < n_grid; j++) {
            run_case(&case_no, grid[i], grid[j], grid[(i + j) % n_grid]);
        }
    }

    for (i = 0; i < n_grid; i++) {
        for (j = 0; j < n_grid; j++) {
            for (k = 0; k < n_grid; k += 4) {
                run_case(&case_no, grid[i], grid[j], grid[k]);
            }
        }
    }

    {
        uint32_t state = 2463534242u;
        int t;
        for (t = 0; t < 600; t++) {
            unsigned char r = (unsigned char)rand_u8(&state);
            unsigned char g = (unsigned char)rand_u8(&state);
            unsigned char b = (unsigned char)rand_u8(&state);
            run_case(&case_no, r, g, b);
        }
    }

    return 0;
}
